style.css:
@-moz-document domain("youtube.com") {
/* Force the neon stars onto the top header bar & clear solid theme covers */
  #masthead-container.ytd-app,
  ytd-masthead,
  ytd-masthead #container.ytd-masthead,
  ytd-masthead #background.ytd-masthead {
    background-color: #120024 !important;
    background-image: url("data:image/svg+xml;base64,") !important;
    background-repeat: repeat !important;
    background-size: 180px 90px !important;
  }

  /* Make sure inner sections of the top bar are transparent so the stars shine through */
  ytd-masthead #start,
  ytd-masthead #center,
  ytd-masthead #end,
  ytd-masthead #buttons {
    background: transparent !important;
  }

  ytd-masthead {
    border-bottom: 2px solid #ff66d9 !important;
    box-shadow: 0 2px 15px rgba(255, 102, 217, 0.6) !important;
  }

  /* Keep ONLY the search bar and microphone dark & glowing */
  ytd-searchbox[mode="legacy"] #container.ytd-searchbox,
  yt-searchbox .ytSearchboxComponentInputBox,
  #voice-search-button button {
    background: rgba(18, 0, 36, 0.85) !important;
    border: 1.5px solid #ff66d9 !important;
    box-shadow: 0 0 8px rgba(255, 102, 217, 0.6) !important;
  }

  /* Comic Sans font inside the search bar */
  ytd-searchbox input#search,
  yt-searchbox input.ytSearchboxComponentInput {
    font-family: "Comic Sans MS", "Comic Sans", "Comic Neue", cursive !important;
    color: #ffccff !important;
  }
}
